package hexadecimal

import (
	"errors"
	"math"
)

// Sentinel errors returned by ParseHex.
var (
	errSyntax = errors.New("invalid hex syntax")
	errRange  = errors.New("value out of range")
)

// ParseHex converts a hexadecimal string (e.g. "10af8c") to its decimal
// equivalent using first principles, without any built-in or external
// conversion libraries.
//
// It returns a syntax error for empty strings or strings containing
// characters that are not valid hexadecimal digits, and a range error if
// the value does not fit in an int64.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, errSyntax
	}

	var value int64
	for _, r := range in {
		digit, ok := hexDigitValue(r)
		if !ok {
			return 0, errSyntax
		}
		// Check for overflow before scaling: the new value would be
		// value*16 + digit, which must not exceed math.MaxInt64.
		if value > (math.MaxInt64-int64(digit))/16 {
			return 0, errRange
		}
		value = value*16 + int64(digit)
	}
	return value, nil
}

// hexDigitValue maps a rune to its hexadecimal digit value (0-15),
// accepting both upper- and lower-case letters.
func hexDigitValue(r rune) (int, bool) {
	switch {
	case r >= '0' && r <= '9':
		return int(r - '0'), true
	case r >= 'a' && r <= 'f':
		return int(r-'a') + 10, true
	case r >= 'A' && r <= 'F':
		return int(r-'A') + 10, true
	}
	return 0, false
}

// HandleErrors takes a list of inputs for ParseHex and returns a matching
// list of error cases: "none", "syntax", or "range".
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		switch {
		case err == nil:
			results[i] = "none"
		case err == errRange:
			results[i] = "range"
		default:
			results[i] = "syntax"
		}
	}
	return results
}

